python3 - <<'E'
p='src/cart.js'
s=open(p).read()
s=s.replace("let i = 1;","let i = 0;")
s=s.replace("""function cartLabel(items) {
  return 'Total: ' + formatPrice(cartTotal(items));
}
""","""// Returns the amount (in cents) a discount takes off the subtotal, never more than the subtotal.
// discount: { type: 'percent', value: 0-100 } or { type: 'fixed', value: cents }
function discountAmount(subtotal, discount) {
  if (!discount) return 0;
  if (!(discount.value >= 0)) throw new Error('Invalid discount value');
  let amount;
  if (discount.type === 'percent') {
    if (discount.value > 100) throw new Error('Invalid discount value');
    amount = Math.round(subtotal * discount.value / 100);
  } else if (discount.type === 'fixed') {
    amount = discount.value;
  } else {
    throw new Error('Unknown discount type: ' + discount.type);
  }
  return Math.min(amount, subtotal);
}

// Returns the cart total after applying an optional discount.
function cartTotalWithDiscount(items, discount) {
  const subtotal = cartTotal(items);
  return subtotal - discountAmount(subtotal, discount);
}

function cartLabel(items, discount) {
  return 'Total: ' + formatPrice(cartTotalWithDiscount(items, discount));
}
""")
s=s.replace("{ cartTotal, cartLabel }","{ cartTotal, cartTotalWithDiscount, discountAmount, cartLabel }")
open(p,'w').write(s)
p='test/cart.test.js'
