s=s.replace("{ cartTotal, cartLabel }","{ cartTotal, cartTotalWithDiscount, cartLabel }")
s+="""
const items = [{ price: 250, qty: 2 }, { price: 100, qty: 1 }];

test('percent discount', () => {
  assert.strictEqual(cartTotalWithDiscount(items, { type: 'percent', value: 10 }), 540);
});

test('fixed discount is capped at subtotal', () => {
  assert.strictEqual(cartTotalWithDiscount(items, { type: 'fixed', value: 100 }), 500);
  assert.strictEqual(cartTotalWithDiscount(items, { type: 'fixed', value: 9999 }), 0);
});

test('no discount leaves total unchanged', () => {
  assert.strictEqual(cartTotalWithDiscount(items), 600);
});

test('invalid discounts throw', () => {
  assert.throws(() => cartTotalWithDiscount(items, { type: 'percent', value: 150 }));
  assert.throws(() => cartTotalWithDiscount(items, { type: 'fixed', value: -5 }));
  assert.throws(() => cartTotalWithDiscount(items, { type: 'bogus', value: 5 }));
});

test('cartLabel applies discount', () => {
  assert.strictEqual(cartLabel([{ price: 1000, qty: 1 }], { type: 'percent', value: 50 }), 'Total: $5.00');
});
"""
open(p,'w').write(s)
